@* Interactive island placed in the static MainLayout header.
   Reacts to ThemeService changes in real time. *@
@implements IDisposable
@inject ThemeService ThemeSvc

<span class="theme-indicator" style="color: @ThemeSvc.AccentColor;" title="Current theme">
    @ThemeIcon @ThemeSvc.Theme
</span>

@code {
    private string ThemeIcon => ThemeSvc.Theme switch
    {
        ThemeMode.Light  => "☀️",
        ThemeMode.Dark   => "🌙",
        _                => "💻"
    };

    protected override void OnInitialized()
        => ThemeSvc.OnChange += HandleThemeChanged;

    private void HandleThemeChanged()
        => InvokeAsync(StateHasChanged);

    public void Dispose()
        => ThemeSvc.OnChange -= HandleThemeChanged;
}

@* Interactive island for quick theme cycling (e.g. in the sidebar). *@
@implements IDisposable
@inject ThemeService ThemeSvc

<button class="btn btn-sm btn-outline-secondary w-100"
        @onclick="CycleTheme"
        title="Toggle theme">
    @ThemeIcon @ThemeSvc.Theme
</button>

@code {
    private string ThemeIcon => ThemeSvc.Theme switch
    {
        ThemeMode.Light  => "☀️",
        ThemeMode.Dark   => "🌙",
        _                => "💻"
    };

    protected override void OnInitialized()
        => ThemeSvc.OnChange += HandleThemeChanged;

    private void CycleTheme()
    {
        ThemeSvc.Theme = ThemeSvc.Theme switch
        {
            ThemeMode.Light  => ThemeMode.Dark,
            ThemeMode.Dark   => ThemeMode.System,
            _                => ThemeMode.Light
        };
    }

    private void HandleThemeChanged()
        => InvokeAsync(StateHasChanged);

    public void Dispose()
        => ThemeSvc.OnChange -= HandleThemeChanged;
}

@page "/settings"
@rendermode InteractiveServer
@implements IDisposable
@inject ThemeService ThemeSvc

<PageTitle>Settings</PageTitle>

<h1>User Preferences</h1>

<div class="card mt-3" style="max-width: 480px;">
    <div class="card-body">
        <h5 class="card-title">Theme</h5>

        <div class="btn-group mb-3" role="group">
            @foreach (var mode in Enum.GetValues<ThemeMode>())
            {
                <button class="btn @(ThemeSvc.Theme == mode ? "btn-primary" : "btn-outline-primary")"
                        @onclick="() => ThemeSvc.Theme = mode">
                    @mode
                </button>
            }
        </div>

        <h5 class="card-title">Accent Color</h5>

        <div class="d-flex align-items-center gap-2 mb-3">
            <input type="color"
                   class="form-control form-control-color"
                   value="@ThemeSvc.AccentColor"
                   @onchange="OnColorChanged" />
            <span style="color: @ThemeSvc.AccentColor;">@ThemeSvc.AccentColor</span>
        </div>

        <p class="text-muted small mb-0">
            Changes apply instantly to all components in this session.
        </p>
    </div>
</div>

@code {
    protected override void OnInitialized()
        => ThemeSvc.OnChange += HandleThemeChanged;

    private void OnColorChanged(ChangeEventArgs e)
        => ThemeSvc.AccentColor = e.Value?.ToString() ?? "#0d6efd";

    private void HandleThemeChanged()
        => InvokeAsync(StateHasChanged);

    public void Dispose()
        => ThemeSvc.OnChange -= HandleThemeChanged;
}

